begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values
 ('10000000-0000-4000-8000-000000000001','sql-a@pacefit.test'),
 ('20000000-0000-4000-8000-000000000002','sql-b@pacefit.test');
insert into public.social_profiles(user_id,display_name) values
 ('10000000-0000-4000-8000-000000000001','A prueba'),
 ('20000000-0000-4000-8000-000000000002','B prueba');
insert into public.city_entries(id,owner_id,kind,label,latitude,longitude,photo_path) values
 ('30000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','PLOGGING','MUCH',0,0,'10000000-0000-4000-8000-000000000001/30000000-0000-4000-8000-000000000003.jpg'),
 ('40000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000002','REPORT','WASTE',0,0,'20000000-0000-4000-8000-000000000002/40000000-0000-4000-8000-000000000004.jpg');
select is((select points from city_entries where id='30000000-0000-4000-8000-000000000003'),20,'points generated by SQL, not client');
select ok((select relrowsecurity from pg_class where oid='public.city_entries'::regclass),'city RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.social_profiles'::regclass),'profile RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.ai_usage'::regclass),'usage RLS enabled');

set local role anon;
select throws_ok('select * from public.city_entries','42501',null,'anonymous cannot read city');
select throws_ok('select * from public.social_profiles','42501',null,'anonymous cannot read profiles');
select throws_ok($$select public.accept_social_profile('Intruso')$$,'42501',null,'anonymous cannot create public profile');
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from city_entries where id in ('30000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004')),2,'authenticated member sees shared city fixtures');
select is((select count(*)::int from social_profiles),1,'user sees only own profile');
select throws_ok($$update city_entries set points=999 where id='30000000-0000-4000-8000-000000000003'$$,'428C9',null,'points cannot be replaced even before privilege checks');
select is((select points from city_entries where id='30000000-0000-4000-8000-000000000003'),20,'forged points did not mutate target');
select throws_ok($$update city_entries set owner_id='10000000-0000-4000-8000-000000000001' where id='40000000-0000-4000-8000-000000000004'$$,'42501',null,'cannot change another owner');
select throws_ok($$delete from city_entries where id='40000000-0000-4000-8000-000000000004'$$,'42501',null,'direct delete denied even with user JWT');
select throws_ok($$select public.set_report_resolved('40000000-0000-4000-8000-000000000004',true)$$,'P0001','Not found','cannot resolve other user report');
select is((select resolved from city_entries where id='40000000-0000-4000-8000-000000000004'),false,'denied RPC did not mutate target');
select throws_ok($$select public.reserve_ai_call('10000000-0000-4000-8000-000000000001','photo')$$,'42501',null,'user cannot bypass gateway quota');
select throws_ok($$insert into storage.objects(bucket_id,name) values('city-photos','10000000-0000-4000-8000-000000000001/50000000-0000-4000-8000-000000000005.jpg')$$,'42501',null,'direct storage upload forbidden');
reset role;

select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.set_report_resolved('40000000-0000-4000-8000-000000000004',true)$$,'owner can resolve own report');
select is((select resolved from city_entries where id='40000000-0000-4000-8000-000000000004'),true,'own RPC changes real row');
reset role;

select ok(public.reserve_ai_call('10000000-0000-4000-8000-000000000001','photo'),'first quota reservation allowed');
do $$begin for i in 2..40 loop perform public.reserve_ai_call('10000000-0000-4000-8000-000000000001','photo'); end loop; end$$;
select is(public.reserve_ai_call('10000000-0000-4000-8000-000000000001','photo'),false,'41st call denied');
select is((select count(*)::int from ai_usage where user_id='10000000-0000-4000-8000-000000000001'),40,'exactly 40 audit rows for fixture user');
insert into ai_usage(user_id,task,created_at) values('20000000-0000-4000-8000-000000000002','photo',now()-interval '31 days');
select lives_ok('select public.purge_ai_usage()','retention task runs');
select is((select count(*)::int from ai_usage where user_id in ('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002')),40,'retention removes fixture records older than 30 days');
update social_profiles set deletion_requested_at=now() where user_id='10000000-0000-4000-8000-000000000001';
select is(public.reserve_ai_call('10000000-0000-4000-8000-000000000001','photo'),false,'deleting account cannot use AI');
select throws_ok($$insert into storage.objects(bucket_id,name) values('city-photos','10000000-0000-4000-8000-000000000001/50000000-0000-4000-8000-000000000005.jpg')$$,'P0001','Account unavailable','even admin upload rejected after deletion starts');
delete from auth.users where id='10000000-0000-4000-8000-000000000001';
select is((select count(*)::int from city_entries where id in ('30000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004')),1,'auth deletion cascades own city and preserves other fixture');
select is((select count(*)::int from ai_usage where user_id='10000000-0000-4000-8000-000000000001'),0,'auth deletion cascades AI audit');
select is((select count(*)::int from private.ai_quota where user_id='10000000-0000-4000-8000-000000000001'),0,'auth deletion cascades quota');
select is((select count(*)::int from social_profiles where user_id in ('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002')),1,'auth deletion preserves other account');
insert into auth.users(id,email) values('60000000-0000-4000-8000-000000000006','sql-no-profile@pacefit.test');
select lives_ok($$select public.begin_account_deletion('60000000-0000-4000-8000-000000000006',repeat('a',64))$$,'deletion can start before public profile exists');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.accept_social_profile('Too late')$$,'P0001','Deletion pending','acceptance cannot recreate profile during deletion');
reset role;
select is((select count(*)::int from social_profiles where user_id='60000000-0000-4000-8000-000000000006'),0,'denied late acceptance did not create profile');
delete from auth.users where id='60000000-0000-4000-8000-000000000006';
select is(public.deletion_completed(repeat('a',64)),true,'receipt survives auth deletion without public profile');
select * from finish();
rollback;
